const PerformanceReport=(()=>{
 const teacherOrder=new Intl.Collator('zh-Hans-CN-u-co-pinyin',{usage:'sort',sensitivity:'base',numeric:true});
 const feeHeader=['姓名','结算项目','学生','课酬','备注'];
 const signHeader=['顾问','试听时间','试听学生','报名课程','试听讲师','辅助签约奖励'];
 function date(value){if(value===undefined||value===null||value==='')return '';const s=String(value);if(/^\d{5}(?:\.\d+)?$/.test(s)){const d=new Date(Date.UTC(1899,11,30)+Math.floor(Number(s))*86400000);return `${d.getUTCFullYear()}/${d.getUTCMonth()+1}/${d.getUTCDate()}`}return s.replace(/^(\d{4})-(\d{2})-(\d{2})$/,(_,y,m,d)=>`${y}/${Number(m)}/${Number(d)}`)}
 function label(e,r){const raw=e.raw||{},t=raw.type||'',p=raw.project||e.project||'';if(t==='项目')return /小项目|创意|基础课/.test(p)?p:'项目'+(p?' '+p:'');if(t){if(r.unit==='小时'&&!/小时|课时|\d\s*h/i.test(t))return t+' '+e.qty+'小时';return t}let s=r.item||'项目';if(r.unit==='小时')return s+' '+e.qty+'小时';if(p)return s+'（项目'+p+'）';return s}
 function build(entries,lookup,calc){const fee=[],sign=[],feeIds=[],signIds=[];for(const e of [...entries].sort((a,b)=>teacherOrder.compare(String(a.teacher||'').trim(),String(b.teacher||'').trim()))){const c=calc(e),r=lookup(e.rule)||{};if(e.nature!=='全职'||c.status!=='可结算')continue;if((r.group||'').includes('签约')||/辅助签约/.test(r.item||'')){const raw=e.raw||{};signIds.push(e.id);sign.push([e.advisor||raw.advisor||'',date(e.trialDate||raw.trialDate||''),e.student,e.enrolledCourse||raw.enrolledCourse||[raw.country,raw.package].filter(Boolean).join(' '),e.teacher,c.amount])}else{const notes=[e.note||''];if(e.ratio!==1)notes.push('特殊结算'+Number((e.ratio*100).toFixed(8))+'%');feeIds.push(e.id);fee.push([e.teacher,label(e,r),e.student,c.amount,notes.filter(Boolean).join('；')])}}return [{name:'课酬-全职',recordIds:feeIds,rows:[feeHeader,...fee],widths:[18,38,18,16,45]},{name:'教师辅助签约奖励-全职',recordIds:signIds,rows:[signHeader,...sign],widths:[18,20,18,35,18,22]}]}
 function select(saved,preview,month){const out=[...saved],ids=new Set(saved.map(e=>e.id)),sources=new Set(saved.map(e=>e.sourceKey).filter(Boolean));for(const e of preview||[]){if(e.month!==month||e.duplicate||ids.has(e.id)||(e.sourceKey&&sources.has(e.sourceKey)))continue;out.push(e);ids.add(e.id);if(e.sourceKey)sources.add(e.sourceKey)}return out}
 return {build,date,select};
})();
function reportEntries(){return PerformanceReport.select(monthEntries(),importPreview,$('month').value)}
function reportSheets(){return PerformanceReport.build(reportEntries(),ruleBy,calculate)}
function reportEmptyReason(entries){if(!entries.length)return '当前月份没有已导入数据或匹配预览，请先上传文件并点击“预览匹配结果”，也请检查结算月份。';const pending=entries.filter(e=>calculate(e).status.startsWith('待')).length;return `当前没有可结算记录（待确认${pending}条，已排除${entries.length-pending}条）。请先核对版本、匹配规则和老师性质；老汉艺项目及作品集审核本来就不计绩效。`}
function renderReport(){const sheets=reportSheets(),entries=reportEntries(),saved=monthEntries(),extra=entries.length-saved.length;const scope=`${$('month').value} · 已导入${saved.length}条 · 预览新增${extra}条 · 可导出${sheets.reduce((n,s)=>n+s.rows.length-1,0)}条。`+(extra?'预览须确认导入后计入工资。':'');$('reportScope').textContent=scope;$('exportScope').textContent=scope;for(const [i,id]of ['feeReport','signReport'].entries())$(id).innerHTML=sheets[i].rows.slice(1).map((row,index)=>{const id=sheets[i].recordIds[index],kind=state.entries.some(e=>e.id===id)?'saved':'preview';return `<tr><td><input type="checkbox" data-report-select="${esc(id)}" aria-label="选择${esc(row[0])} ${esc(i===0?row[2]:row[2])}的绩效" style="width:auto"></td>`+row.map((v,c)=>`<td${c===1||c===row.length-1?' class="wrap"':''}>${typeof v==='number'?money(v):esc(v)}</td>`).join('')+`<td><button class="danger" data-performance-delete="${esc(id)}" data-delete-kind="${kind}">删除</button></td></tr>`}).join('')||`<tr><td colspan="${sheets[i].rows[0].length+2}">暂无可结算记录。</td></tr>`}
function previewVersionReady(){if(!$('confirmDefault').checked&&importPreview.some(e=>!e.duplicate&&e.versionDefault&&!e.excludedReason)){toast('当前预览有未指定版本的老师，请先设置员工版本，或勾选“未指定版本的老师先按常规版”。');return false}return true}
async function exportPerformanceReport(){try{if(!previewVersionReady())return;const entries=reportEntries(),sheets=reportSheets();if(!sheets.some(s=>s.rows.length>1)){const reason=reportEmptyReason(entries);toast(reason);$('importStats').textContent=reason;showTab('import');return}const pending=entries.filter(e=>calculate(e).status.startsWith('待'));if(pending.length&&!confirm('有'+pending.length+'条待确认，本报表仅导出可结算绩效。待确认记录可在工具内继续核对。是否导出？'))return;download(await ExcelIO.write(sheets),$('month').value+'绩效报表.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}catch(err){toast('导出失败：'+err.message)}}
for(const id of ['excelExport','excelExportTop','reportExport'])$(id).onclick=exportPerformanceReport;
const renderBeforeReport=render;render=function(){renderBeforeReport();renderReport()};
$('month').addEventListener('change',renderReport);$('onlyVisible').addEventListener('change',renderReport);
const drawPreviewBeforeReport=drawPreview;drawPreview=function(){drawPreviewBeforeReport();renderReport()};
const invalidateBeforeReport=invalidatePreview;invalidatePreview=function(){invalidateBeforeReport();renderReport()};
renderReport();
